import{z as s,x as o,o as B,c as D,q as l,j as i,D as A,d as e,s as r,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"限额体系","description":"","frontmatter":{"title":"限额体系","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rk-limit-system.md","filePath":"quant/rk-limit-system.md","lastUpdated":1791063341000}'),d={name:"quant/rk-limit-system.md"};function m(C,E,p,F,u,h){const t=o("Mermaid");return B(),D("div",null,[E[2]||(E[2]=l('<h1 id="限额体系" tabindex="-1">限额体系 <a class="header-anchor" href="#限额体系" aria-label="Permalink to &quot;限额体系&quot;">​</a></h1><div class="epigraph"><p>限额是风险偏好的兑换汇率：董事会说「能承受多少」，限额把它翻译成每张桌面上的一串数字；翻译不走样，靠层级与口径。</p><footer>—— 据 Jorion, *Value at Risk*；Matten, *Managing Bank Capital*, 2000 整理</footer></div><p><a href="/quant/rk-attribution">上一课</a>把总风险拆成各分部的组成贡献、把损益对到未解释残差。拆出来要有人负责，负责的边界就是限额。<a href="/quant/mm-risk-limits">做市风控与限额</a>已给出交易台一层的先例；本课升一层，搭机构的限额体系：从董事会风险偏好到账簿约束的翻译，以及违例程序。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>限额体系的病在上中下三段。上段脱节：风险偏好是年报里的一句话，桌面限额是另一套拍出来的数字，中间没有换算路径，偏好成了修辞。中段混口径：名义、希腊字母、VaR、止损堆在同一张清单里互相打架——利率掉期簿的名义动辄百亿而 DV01 有限，按名义管理毫无信息量；反过来，只用灵敏度管理，对冲后的凸性尾巴与流动性极差的持仓又被放走。下段无程序：突破限额靠口头豁免，台账缺失，限额退化成建议。错在哪：每种口径只覆盖一种失败模式，单一口径的限额体系必然在它不管的维度上漏，漏出的头寸没有记录，下次灾难从那里进出。</p><p><span class="marginnote">术语翻译：DV01 是「利率动 1 个基点（0.01%），组合价值变多少」——掉期簿的风险体温计。名义本金百亿的掉期，DV01 可能只有几百万：名义说「你签了多大的合同」，DV01 说「你实际怕利率动多少」。限额用错口径，就像用体重去管血压。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>翻译链四层。董事会风险偏好：以资本表达——目标评级与资本充足缓冲。组合层：总 <a href="/quant/expected-shortfall">Expected Shortfall</a> 限额与关键压力情景限额，分母是经济资本减缓冲（算法见下一课）。桌面层：VaR/ES 子限额、Delta/Gamma/Vega 敏感度限额、集中度限额，配额按上一课的组成贡献与边际贡献协商。账簿层：止损与回撤限额、名义与流动性约束。口径分工：止损管已实现的累积损失，不依赖模型；VaR/ES 管前瞻分布，随市场状态自动松紧；名义与流动性约束管「按市值出不去」的头寸；敏感度限额圈定局部近似的可信范围。违例程序是体系的执行件：先分类（技术性故障还是实质超险），带时限、上报路径与恢复计划，豁免一律书面登记带期限；违例率是校准信号：长期不触是过松，频繁触是过紧或模型漂移。</p>',8)),(B(),i(n,null,{default:A(()=>[r(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E4%B8%80%E7%AC%94%E5%A4%B4%E5%AF%B8%E8%BF%9B%E5%9C%BA%EF%BC%8C%E8%B0%81%E7%AE%A1%E5%AE%83%E7%9A%84%E5%93%AA%E7%A7%8D%E5%A4%B1%E8%B4%A5%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%20A%5B%22%E6%AD%A2%E6%8D%9F%E9%99%90%E9%A2%9D%EF%BC%9A%E6%88%AA%E6%96%AD%E5%B7%B2%E5%AE%9E%E7%8E%B0%E7%9A%84%E7%B4%AF%E7%A7%AF%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20Q%20--%3E%20B%5B%22VaR%2FES%20%E9%99%90%E9%A2%9D%EF%BC%9A%E7%AE%A1%E5%89%8D%E7%9E%BB%E5%88%86%E5%B8%83%E7%9A%84%E5%B0%BE%E9%83%A8%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E6%95%8F%E6%84%9F%E5%BA%A6%E9%99%90%E9%A2%9D%EF%BC%9A%E5%9C%88%E5%AE%9A%20Delta%2FGamma%2FVega%20%E5%B1%80%E9%83%A8%E8%BF%91%E4%BC%BC%E5%8F%AF%E4%BF%A1%E5%8C%BA%22%5D%0A%20%20Q%20--%3E%20D%5B%22%E5%90%8D%E4%B9%89%E4%B8%8E%E6%B5%81%E5%8A%A8%E6%80%A7%E9%99%90%E9%A2%9D%EF%BC%9A%E7%AE%A1%E6%8C%89%E5%B8%82%E5%80%BC%E5%87%BA%E4%B8%8D%E5%8E%BB%E7%9A%84%E8%A7%84%E6%A8%A1%22%5D%0A%20%20A%20--%3E%20E%5B%22%E5%9B%9B%E7%B1%BB%E5%B9%B6%E6%8E%92%EF%BC%8C%E5%BD%BC%E6%AD%A4%E6%8E%A5%E4%BD%8F%E5%AF%B9%E6%96%B9%E7%9A%84%E7%9B%B2%E5%8C%BA%22%5D%0A%20%20B%20--%3E%20E%0A%20%20C%20--%3E%20E%0A%20%20D%20--%3E%20E%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"Jorion 的经典提醒：限额要绑定损失容忍度而不是报告习惯。\\(99\\%\\) 十日 VaR 限额设在年风险预算的 \\(16\\%\\) 左右（一年约 \\(25\\) 个不重叠十日窗，单窗超限概率约 \\(8\\%\\)），数字从偏好推出——直接按「去年用量的百分之一百一」定限额，是把现状当偏好。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"为什么多口径并存是特性而非混乱：代理偏差不可消除，只能并排覆盖。名义限额便宜、难被模型骗，适合约束低流动性的绝对规模；希腊字母精确但只在局部成立，大波动外没有约束力；ES 限额直达尾部却依赖整个流水线的质量；止损不预测只截断，把「继续错」的成本封顶。四类并排，各自失败的维度被彼此接住。限额与计量的耦合要显式：上一课的损益归因给出每张桌的真实风险行为，条件波动收紧计量时，同等限额下的可用风险预算自动收缩，平静期的虚高利用不构成隐性加杠杆。豁免文化决定体系生死：一次无痕豁免教会的不是这次例外，而是限额可以谈。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"数字实例：同一张债券头寸，十日 99% VaR 可能是 800 万，而历史最大回撤曾达 5000 万。VaR 限额管「平常日子的尾部」，止损限额管「累计亏到哪必须停」——只设 VaR，单边趋势里没有闸；只设止损，事前的前瞻风险无人约束。")],-1)),(B(),i(n,null,{default:A(()=>[r(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E8%91%A3%E4%BA%8B%E4%BC%9A%E9%A3%8E%E9%99%A9%E5%81%8F%E5%A5%BD%EF%BC%9A%E8%B5%84%E6%9C%AC%E8%A1%A8%E8%BE%BE%22%5D%20--%3E%20PORT%5B%22%E7%BB%84%E5%90%88%E9%99%90%E9%A2%9D%EF%BC%9AES%20%E4%B8%8E%E5%8E%8B%E5%8A%9B%22%5D%0A%20%20PORT%20--%3E%20DESK%5B%22%E6%A1%8C%E9%9D%A2%E9%99%90%E9%A2%9D%EF%BC%9A%E8%AE%A1%E9%87%8F%E3%80%81%E6%95%8F%E6%84%9F%E5%BA%A6%E3%80%81%E9%9B%86%E4%B8%AD%E5%BA%A6%22%5D%0A%20%20DESK%20--%3E%20BOOK%5B%22%E8%B4%A6%E7%B0%BF%EF%BC%9A%E6%AD%A2%E6%8D%9F%E3%80%81%E5%90%8D%E4%B9%89%E3%80%81%E6%B5%81%E5%8A%A8%E6%80%A7%22%5D%0A%20%20ATTR%5B%22%E5%BD%92%E5%9B%A0%EF%BC%9A%E7%BB%84%E6%88%90%E8%B4%A1%E7%8C%AE%22%5D%20--%3E%7C%22%E9%85%8D%E9%A2%9D%E5%8D%8F%E5%95%86%22%7C%20DESK%0A%20%20BOOK%20--%3E%20UTIL%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%E4%B8%8E%E8%BF%9D%E4%BE%8B%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20UTIL%20--%3E%7C%22%E6%A0%A1%E5%87%86%E4%BF%A1%E5%8F%B7%22%7C%20PORT%0A%20%20UTIL%20--%3E%7C%22%E8%B1%81%E5%85%8D%E7%99%BB%E8%AE%B0%22%7C%20AUD%5B%22%E5%AE%A1%E8%AE%A1%E4%B8%8E%E6%B2%BB%E7%90%86%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>限额数量有上限：指标多过可监控范围，每个都失效，宁少而必查。限额不替代定价：内部过账价与资本收费是让限额「不用到顶」的配套，只靠限额硬拦的交易台会把交易推到限额边缘——这正是下一课资本配置要解的激励问题。做市台的库存与报价限额有更细的时效结构，本课只提供层级接口。跨市场的保证金规则与追缴频率改变同一限额的实际松紧，全球账户按最紧口径统一。</p><p><span class="marginnote">常见误区：以为限额被触发等于有人犯错。设计良好的限额会被正常波动触发，违例程序与豁免台账就是为此准备的；真正危险的是从不触发的限额（过松）与总能口头豁免的限额（形同虚设）。违例率是校准仪表，不是处分依据。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>限额体系是风险偏好的逐层翻译：偏好以资本表达，组合、桌面、账簿各有口径。</li><li>每种口径覆盖一种失败模式：止损截断累积、ES 管前瞻、名义管流动性、希腊管局部。</li><li>配额以归因的组成贡献为据；条件波动让实际预算随市场状态自动收缩。</li><li>违例程序与豁免台账是执行件；违例率是限额校准的信号。</li><li>出处：Jorion, <em>Value at Risk</em>；Matten, <em>Managing Bank Capital</em>, 2000；BCBS 内部资本充足评估原则（ICAAP）；交易台一层先例见本站做市风控与限额课。</li></ul>',5))])}const V=s(d,[["render",m]]);export{T as __pageData,V as default};
